// Build comprehensive property data and prompt
const body = $json.body || {};
const comparables = $('Query Comparable Sales').item.json.data || [];
const marketData = $('Query Market Conditions').item.json?.data?.[0] || {};

// Format comparables for the prompt
const formatComparable = (comp, index) => {
  if (!comp) return `Comparable ${index}: No data available`;
  const features = Array.isArray(comp.features) ? comp.features.join(', ') : (comp.features || 'None');
  return `Comparable ${index}:
  - Address: ${comp.address || 'N/A'}
  - Sale Price: R${comp.sale_price?.toLocaleString() || 'N/A'}
  - Sale Date: ${comp.sale_date || 'N/A'}
  - Bedrooms: ${comp.bedrooms || 'N/A'}
  - Bathrooms: ${comp.bathrooms || 'N/A'}
  - Floor Size: ${comp.floor_size || 'N/A'} sqm
  - Stand Size: ${comp.stand_size || 'N/A'} sqm
  - Condition: ${comp.condition || 'N/A'}
  - Features: ${features}`;
};

const comparablesText = comparables.length > 0
  ? comparables.slice(0, 5).map((c, i) => formatComparable(c, i + 1)).join('\n\n')
  : 'No comparable sales found in the last 6 months.';

// Calculate market averages
const avgPricePerSqm = comparables.length > 0 && comparables[0].floor_size
  ? Math.round(comparables.reduce((sum, c) => sum + (c.sale_price / (c.floor_size || 1)), 0) / comparables.length)
  : 0;

const avgSalePrice = comparables.length > 0
  ? Math.round(comparables.reduce((sum, c) => sum + c.sale_price, 0) / comparables.length)
  : 0;

const features = Array.isArray(body.features) ? body.features.join(', ') : (body.features || 'None specified');

const prompt = `Recommend listing price for this property:

SUBJECT PROPERTY:
Address: ${body.address || 'Unknown'}
Suburb: ${body.suburb || 'Unknown'}
City: ${body.city || 'South Africa'}
Type: ${body.property_type || 'House'}
Bedrooms: ${body.bedrooms || '0'}
Bathrooms: ${body.bathrooms || '0'}
Garages: ${body.garages || '0'}
Floor Size: ${body.floor_size || '0'} sqm
Stand Size: ${body.stand_size || '0'} sqm
Condition: ${body.condition || 'Good'}
Features: ${features}

COMPARABLE SALES (last 6 months):
${comparablesText}

MARKET CONDITIONS:
Average days on market: ${marketData.avg_days_on_market || '45'}
Market trend: ${marketData.market_trend || 'stable'}
Inventory levels: ${marketData.inventory_levels || 'normal'}
Average price per sqm in area: R${avgPricePerSqm || 'market rate'}
Average sale price in area: R${avgSalePrice?.toLocaleString() || 'N/A'}

Return JSON:
{
  "recommended_price_range": {
    "minimum": 0,
    "target": 0,
    "maximum": 0
  },
  "price_per_sqm": {
    "subject_estimate": 0,
    "comparable_average": ${avgPricePerSqm},
    "market_average": ${avgPricePerSqm}
  },
  "pricing_strategy": "aggressive|competitive|conservative",
  "days_on_market_estimate": 0,
  "market_positioning": "top_10|above_average|average|below_average",
  "key_value_factors": ["factors adding value"],
  "value_concerns": ["factors reducing value"],
  "comparables_analysis": {
    "most_similar": "address",
    "adjustments_needed": ["list adjustments"]
  },
  "recommendation_summary": "brief summary for agent",
  "confidence": 0.0-1.0
}`;

return [{
  json: {
    property_data: body,
    comparables: comparables,
    market_data: marketData,
    avg_price_per_sqm: avgPricePerSqm,
    avg_sale_price: avgSalePrice,
    prompt: prompt
  }
}];

// Parse Groq AI response
const groqResponse = $json;
const content = groqResponse.choices?.[0]?.message?.content || '{}';
const propertyData = $('Prepare Property Data').item.json.property_data;
const comparables = $('Prepare Property Data').item.json.comparables;

// Extract JSON from response
let parsed;
try {
  // Try to find JSON in markdown code blocks or raw
  const jsonMatch = content.match(/```json\\s*([\\s\\S]*?)```/) || content.match(/\\{[\\s\\S]*\\}/);
  const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : content;
  parsed = JSON.parse(jsonStr);
} catch (e) {
  // Fallback if JSON parsing fails
  console.log('JSON parse error:', e.message);
  parsed = {
    recommended_price_range: {
      minimum: propertyData.estimated_value ? propertyData.estimated_value * 0.9 : 0,
      target: propertyData.estimated_value || 0,
      maximum: propertyData.estimated_value ? propertyData.estimated_value * 1.1 : 0
    },
    price_per_sqm: {
      subject_estimate: 0,
      comparable_average: 0,
      market_average: 0
    },
    pricing_strategy: 'competitive',
    days_on_market_estimate: 45,
    market_positioning: 'average',
    key_value_factors: ['Location', 'Size'],
    value_concerns: ['Parse error - manual review needed'],
    comparables_analysis: {
      most_similar: 'unknown',
      adjustments_needed: ['Unable to analyze due to parse error']
    },
    recommendation_summary: 'AI analysis returned invalid format. Manual price review recommended.',
    confidence: 0.3
  };
}

// Ensure all required fields exist with defaults
const result = {
  property_id: propertyData.id || 'temp-' + Date.now(),
  property_address: propertyData.address || 'Unknown',
  suburb: propertyData.suburb || 'Unknown',
  recommended_min: parsed.recommended_price_range?.minimum || parsed.recommended_price_range?.min || 0,
  recommended_target: parsed.recommended_price_range?.target || parsed.recommended_price_range?.target_price || 0,
  recommended_max: parsed.recommended_price_range?.maximum || parsed.recommended_price_range?.max || 0,
  price_per_sqm_estimate: parsed.price_per_sqm?.subject_estimate || 0,
  pricing_strategy: parsed.pricing_strategy || 'competitive',
  days_on_market_estimate: parsed.days_on_market_estimate || 45,
  market_positioning: parsed.market_positioning || 'average',
  key_value_factors: parsed.key_value_factors || [],
  value_concerns: parsed.value_concerns || [],
  comparables_used: comparables.slice(0, 5).map(c => ({
    address: c.address,
    sale_price: c.sale_price,
    sale_date: c.sale_date,
    floor_size: c.floor_size,
    bedrooms: c.bedrooms,
    bathrooms: c.bathrooms
  })),
  recommendation_summary: parsed.recommendation_summary || 'Price recommendation generated',
  confidence: parsed.confidence || 0.5,
  comparables_analysis: parsed.comparables_analysis || {
    most_similar: 'unknown',
    adjustments_needed: []
  },
  generated_at: new Date().toISOString(),
  raw_response: content.substring(0, 2000) // Store truncated response for debugging
};

return [{
  json: result
}];

